pub open spec fn election_safety(h: History) -> bool {
    forall |i: int, j: int| #![trigger h.events[i], h.events[j]] 0 <= i < h.events.len() && 0 <= j < h.events.len() ==>
        match (h.events[i], h.events[j]) {
