use crate::test_support::{create_node, start_node, kill};
use madsim::net::NetSim;
use madsim::{time::*, runtime::Handle};
use std::{
    collections::HashMap,
    net::SocketAddr,
    sync::{Arc, Mutex},
};

use super::{client::Clerk, server::ShardCtrler};

pub struct Tester {
    handle: Handle,
    n: usize,
    addrs: Vec<SocketAddr>,
    servers: Mutex<Vec<Option<Arc<ShardCtrler>>>>,

    // begin()/end() statistics
    t0: Instant,
}

impl Tester {
    pub async fn new(n: usize, unreliable: bool) -> Tester {
        let handle = Handle::current();
        let addrs = (0..n)
                .map(|i| SocketAddr::from(([0, 0, 1, i as _], 1)))
                .collect::<Vec<_>>();
        for &addr in &addrs { create_node(&handle, addr); }
        if unreliable {
            NetSim::current().update_config(|cfg| {
                cfg.packet_loss_rate = 0.1;
                cfg.send_latency = Duration::from_millis(1)..Duration::from_millis(27);
            });
        }
        let mut servers = vec![];
        servers.resize_with(n, || None);
        let tester = Tester {
            handle,
            n,
            addrs,
            servers: Mutex::new(servers),
            t0: Instant::now(),
        };
        // create a full set of KV servers.
        for i in 0..n {
            tester.start_server(i).await;
        }
        tester
    }

    fn rpc_total(&self) -> u64 {
        NetSim::current().stat().msg_count / 2
    }

    fn check_timeout(&self) {
        // enforce a two minute real-time limit on each test
        if self.t0.elapsed() > Duration::from_secs(120) {
            panic!("test took longer than 120 seconds");
        }
    }

    // Create a clerk with clerk specific server names.
    // Give it connections to all of the servers, but for
    // now enable only connections to servers in to[].
    pub fn make_client(&self) -> Clerk {
        Clerk::new(self.addrs.clone())
    }

    /// Shutdown a server.
    pub fn shutdown_server(&self, i: usize) {
        debug!("shutdown_server({})", i);
        kill(&self.handle, self.addrs[i]);
        self.servers.lock().unwrap()[i] = None;
    }

    /// Start a server.
    /// If restart servers, first call shutdown_server
    pub async fn start_server(&self, i: usize) {
        debug!("start_server({})", i);
        let addrs = self.addrs.clone();
        let handle = start_node(&self.handle, self.addrs[i]);
        let kv = handle.spawn(ShardCtrler::new(addrs, i, None)).await.unwrap();
        self.servers.lock().unwrap()[i] = Some(kv);
    }

    pub fn leader(&self) -> Option<usize> {
        let servers = self.servers.lock().unwrap();
        for (i, kv) in servers.iter().enumerate() {
            if let Some(kv) = kv {
                if kv.is_leader() {
                    return Some(i);
                }
            }
        }
        None
    }

    /// End a Test -- the fact that we got here means there
    /// was no failure.
    /// print the Passed message,
    /// and some performance numbers.
    pub fn end(&self) {
        self.check_timeout();

        // real time
        let t = self.t0.elapsed();
        // number of Raft peers
        let npeers = self.n;
        // number of RPC sends
        let nrpc = self.rpc_total();

        info!("  ... Passed --");
        info!("  {:?}  {} {}", t, npeers, nrpc);
    }
}

impl Clerk {
    pub async fn check(&self, groups: &[u64]) {
        debug!("check: {:?}", groups);
        let c = self.query().await;
        assert_eq!(c.groups.len(), groups.len());
        // are the groups as expected?
        for gid in groups {
            assert!(c.groups.contains_key(gid), "missing group {}", gid);
        }
        // any un-allocated shards?
        if groups.is_empty() {
            for (shard, gid) in c.shards.iter().enumerate() {
                assert!(
                    *gid == 0 || c.groups.contains_key(gid),
                    "shard {} -> invalid group {}",
                    shard,
                    gid
                );
            }
        }
        // more or less balanced sharding?
        let mut counts = HashMap::<u64, usize>::new();
        for &gid in c.shards.iter() {
            *counts.entry(gid).or_default() += 1;
        }
        if !c.groups.is_empty() {
            let counts = c.groups.keys().map(|gid| *counts.get(gid).unwrap_or(&0));
            let min = counts.clone().min().unwrap();
            let max = counts.clone().max().unwrap();
            assert!(
                max <= min + 1,
                "imbalanced sharding, max {} too much larger than min {}: {:?}",
                max,
                min,
                c.shards,
            );
        }
    }
}

//! Host-only MadSim 0.2 test plumbing. No protocol decisions live here.
use madsim::{runtime::{Handle, NodeHandle}, task::NodeId};
use std::net::SocketAddr;

pub fn node(handle: &Handle, addr: SocketAddr) -> NodeHandle {
    handle.get_node(addr.to_string()).expect("test node created before use")
}

pub fn create_node(handle: &Handle, addr: SocketAddr) -> NodeHandle {
    handle.create_node().name(addr.to_string()).ip(addr.ip()).build()
}

pub fn node_id(handle: &Handle, addr: SocketAddr) -> NodeId {
    node(handle, addr).id()
}

pub fn start_node(handle: &Handle, addr: SocketAddr) -> NodeHandle {
    let id = node_id(handle, addr);
    if handle.is_exit(id) {
        handle.restart(id);
    }
    handle.get_node(id).unwrap()
}

pub fn kill(handle: &Handle, addr: SocketAddr) {
    if let Some(node) = handle.get_node(addr.to_string()) {
        handle.kill(node.id());
    }
}

#[madsim::test]
async fn restart_preserves_node_and_simulated_file() {
    use madsim::{fs, time::{sleep, Duration}};
    let handle = Handle::current();
    let addr = "10.0.0.1:1".parse().unwrap();
    let host = create_node(&handle, addr);
    let id = host.id();
    host.spawn(async {
        let f = fs::File::create("probe").await.unwrap();
        f.write_all_at(b"durable", 0).await.unwrap();
        f.sync_all().await.unwrap();
    }).await.unwrap();
    let pending = host.spawn(async { sleep(Duration::from_secs(10)).await; });
    kill(&handle, addr);
    assert!(pending.await.is_err());
    let restarted = start_node(&handle, addr);
    assert_eq!(restarted.id(), id);
    let bytes = restarted.spawn(async { fs::read("probe").await.unwrap() }).await.unwrap();
    assert_eq!(bytes, b"durable");
}

